#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../gru-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
std::vector<half>fixture(int n,int mul,int add){std::vector<half>a(n);for(int i=0;i<n;i++)a[i]=__float2half(float((i*mul+add)%257-128)/128.f);return a;}
int main(int argc,char**argv){int h=256,batch=64,n=h*batch,repeat=argc>1?atoi(argv[1]):100;auto input=fixture(3*n,13,7),hidden=fixture(3*n,37,11),b1=fixture(3*h,17,3),b2=fixture(3*h,29,5),hx=fixture(n,43,19);std::vector<half>yr(n),sr(5*n),y(n),s(5*n);std::vector<float>got(6*n);reference<half,float,int>(input.data(),hidden.data(),b1.data(),b2.data(),hx.data(),yr.data(),sr.data(),h,n);half *di,*dh,*db1,*db2,*dx,*dy,*ds;CK(cudaMalloc(&di,3*n*2));CK(cudaMalloc(&dh,3*n*2));CK(cudaMalloc(&db1,3*h*2));CK(cudaMalloc(&db2,3*h*2));CK(cudaMalloc(&dx,n*2));CK(cudaMalloc(&dy,n*2));CK(cudaMalloc(&ds,5*n*2));CK(cudaMemcpy(di,input.data(),3*n*2,cudaMemcpyHostToDevice));CK(cudaMemcpy(dh,hidden.data(),3*n*2,cudaMemcpyHostToDevice));CK(cudaMemcpy(db1,b1.data(),3*h*2,cudaMemcpyHostToDevice));CK(cudaMemcpy(db2,b2.data(),3*h*2,cudaMemcpyHostToDevice));CK(cudaMemcpy(dx,hx.data(),n*2,cudaMemcpyHostToDevice));auto launch=[&](){gru_cell_forward<half,float,int><<<n/256,256>>>(di,dh,db1,db2,dx,dy,ds,h,n);};launch();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int k=0;k<repeat;k++)launch();CK(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;CK(cudaMemcpy(y.data(),dy,n*2,cudaMemcpyDeviceToHost));CK(cudaMemcpy(s.data(),ds,5*n*2,cudaMemcpyDeviceToHost));float ma=0,mr=0;bool ok=true;for(int i=0;i<6*n;i++){float g=i<n?__half2float(y[i]):__half2float(s[i-n]),ref=i<n?__half2float(yr[i]):__half2float(sr[i-n]),e=fabsf(g-ref);got[i]=g;ma=fmaxf(ma,e);mr=fmaxf(mr,e/fmaxf(fabsf(ref),1.1920929e-7f));ok&=std::isfinite(g)&&e<=1e-3f;}all&=ok;char file[100];sprintf(file,"gru_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(got.data(),4,got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"gru_cell_forward_including_all_five_saved_states_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",6*n,ma,mr,repeat,file,6*n);}for(auto p:{di,dh,db1,db2,dx,dy,ds})CK(cudaFree(p));puts(all?"PASS":"FAIL");return all?0:1;}
